119	/**
120	 * Creates an excerpt of a Markdown file. This function will:
121	 *
122	 * - Ignore h1 headings (setext or atx)
123	 * - Ignore import/export
124	 * - Ignore code blocks
125	 *
126	 * And for the first contentful line, it will strip away most Markdown
127	 * syntax, including HTML tags, emphasis, links (keeping the text), etc.
128	 */
129	export function createExcerpt(fileString: string): string | undefined {
130	  const fileLines = fileString
131	    .trimStart()
132	    // Remove Markdown alternate title
133	    .replace(/^[^\r\n]*\r?\n[=]+/g, '')
134	    .split(/\r?\n/);
135	  let inCode = false;
136	  let inImport = false;
137	  let lastCodeFence = '';
138	
139	  for (const fileLine of fileLines) {
140	    // An empty line marks the end of imports
141	    if (!fileLine.trim() && inImport) {
142	      inImport = false;
143	    }
144	
145	    // Skip empty line.
146	    if (!fileLine.trim()) {
147	      continue;
148	    }
149	
150	    // Skip import/export declaration.
151	    if ((/^(?:import|export)\s.*/.test(fileLine) || inImport) && !inCode) {
152	      inImport = true;
153	      continue;
154	    }
155	
156	    // Skip code block line.
157	    if (fileLine.trim().startsWith('```')) {
158	      const codeFence = fileLine.trim().match(/^`+/)![0]!;
159	      if (!inCode) {
160	        inCode = true;
161	        lastCodeFence = codeFence;
162	        // If we are in a ````-fenced block, all ``` would be plain text instead
163	        // of fences
164	      } else if (codeFence.length >= lastCodeFence.length) {
165	        inCode = false;
166	      }
167	      continue;
168	    } else if (inCode) {
169	      continue;
170	    }
171	
172	    const cleanedLine = fileLine
173	      // Remove HTML tags.
174	      .replace(/<[^>]*>/g, '')
175	      // Remove Title headers
176	      .replace(/^#[^#]+#?/gm, '')
177	      // Remove Markdown + ATX-style headers
178	      .replace(/^#{1,6}\s*(?<text>[^#]*?)\s*#{0,6}/gm, '$1')
179	      // Remove emphasis.
180	      .replace(/(?<opening>[*_]{1,3})(?<text>.*?)\1/g, '$2')
181	      // Remove strikethroughs.
182	      .replace(/~~(?<text>\S.*\S)~~/g, '$1')
183	      // Remove images.
184	      .replace(/!\[(?<alt>.*?)\][[(].*?[\])]/g, '$1')
185	      // Remove footnotes.
186	      .replace(/\[\^.+?\](?:: .*$)?/g, '')
187	      // Remove inline links.
188	      .replace(/\[(?<alt>.*?)\][[(].*?[\])]/g, '$1')
189	      // Remove inline code.
190	      .replace(/`(?<text>.+?)`/g, '$1')
191	      // Remove blockquotes.
192	      .replace(/^\s{0,3}>\s?/g, '')
193	      // Remove admonition definition.
194	      .replace(/:::.*/, '')
195	      // Remove Emoji names within colons include preceding whitespace.
196	      .replace(/\s?:(?:::|[^:\n])+:/g, '')
197	      // Remove custom Markdown heading id.
198	      .replace(/\{#*[\w-]+\}/, '')
199	      .trim();
200	
201	    if (cleanedLine) {
202	      return cleanedLine;
203	    }
204	  }
205	
206	  return undefined;
207	}
